const item = $input.first().json;
const question = item.question || item.query || item.prompt || '';
const qLower = question.toLowerCase();

let projectFilter = null;
if (qLower.includes('temsa')) projectFilter = 'PRJ-TEMSA';
else if (qLower.includes('vortex')) projectFilter = 'PRJ-VORTEX';
else if (qLower.includes('eldor') || qLower.includes('obc')) projectFilter = 'PRJ-ELDOR-OBC';
else if (qLower.includes('akıllı fabrika') || qLower.includes('kestirimci')) projectFilter = 'PRJ-SMART-FACTORY';
else if (qLower.includes('autosar')) projectFilter = 'PRJ-AUTOSAR-ECU';

return [{
  json: {
    question: question,
    project_filter: projectFilter
  }
}];

const items = $input.all();
const question = $('Normalize Question & Extract Project').first().json.question;

if (!items || items.length === 0 || !items[0].json.content) {
  return [{
    json: {
      question: question,
      context: 'Herhangi bir ilgili proje e-postası bulunamadı.',
      sources: [],
      skip_llm: true
    }
  }];
}

let contextText = '';
const sources = [];
items.forEach((item, idx) => {
  const row = item.json;
  contextText += `--- E-POSTA ${idx + 1} ---\n`;
  contextText += `Konu: ${row.subject}\nGönderen: ${row.from_address}\nTarih: ${row.received_at}\nProje: ${row.project_name} (${row.project_code})\nİçerik:\n${row.content}\n\n`;
  sources.push({
    subject: row.subject,
    from: row.from_address,
    date: row.received_at,
    project: row.project_code,
    similarity: row.similarity
  });
});

const prompt = `Sen Eldor/NISO AI kurumsal yönetim asistanısın. Aşağıdaki doğrulanmış şirket içi proje e-postalarını inceleyerek yöneticinin sorusunu Türkçe olarak profesyonelce cevapla.\n\nKURAL:\n1. Yalnızca verilen e-posta bağlamındaki gerçek bilgilere dayan.\n2. Bilmediğin veya bağlamda olmayan konularda asla tahmin yapma.\n3. Kararları, açık riskleri, teslim tarihlerini ve aksiyon sahiplerini maddeler halinde net belirt.\n\nE-POSTA BAĞLAMI:\n${contextText}\nSORU: ${question}\n\nCEVAP:`;

return [{
  json: {
    question: question,
    prompt: prompt,
    sources: sources,
    skip_llm: false
  }
}];

const promptItem = $('Build Context & Prompt').first().json;
const llmRes = $input.first()?.json || {};

let answer = (llmRes.response || '').trim();
if (!answer && llmRes.thinking) {
  const match = llmRes.thinking.match(/(\n\*\*[A-ZÇĞİÖŞÜ][\s\S]+)/i) || llmRes.thinking.match(/(\n#[\s\S]+)/i);
  if (match) answer = match[0].trim();
}
if (!answer) {
  answer = promptItem.sources && promptItem.sources.length > 0
    ? `**Proje E-posta Özeti:**\n` + promptItem.sources.map(s => `- **${s.subject}** (${s.project || 'Genel'})`).join('\n')
    : 'İlgili e-postalara ulaşılamadı veya cevap üretilemedi.';
}

return [{
  json: {
    status: 'SUCCESS',
    intent: 'PROJECT_MAIL',
    title: 'Proje E-postası (RAG)',
    answer: answer,
    route_used: 'PROJECT_MAIL',
    sources: promptItem.sources || [],
    source_count: promptItem.sources ? promptItem.sources.length : 0,
    is_synthetic: promptItem.sources ? promptItem.sources.some(s => s.reference_id && String(s.reference_id).startsWith('MSG-gm_th_')) : false,
    timestamp: new Date().toISOString()
  }
}];
